const raw = $input.first().json?.choices?.[0]?.message?.content ?? '{}';
let data = {};
try { data = JSON.parse(raw); } catch (e) { data = {}; }
const str = (v, max) => (typeof v === 'string' ? v : '').replace(/\s+/g, ' ').trim().slice(0, max);
const fields = {
  fullName: str(data.fullName, 120),
  phone: str(data.phone, 30),
  industry: str(data.industry, 120),
};
const digits = fields.phone.replace(/\D/g, '').length;
const missing = [];
if (fields.fullName.length < 2) missing.push('fullName');
if (digits < 6) missing.push('phone');
if (fields.industry.length < 2) missing.push('industry');
return [{ json: { fields, missing, complete: missing.length === 0 } }];
